(()=>{const app=document.querySelector('#app');const legacyRender=window.render;function legacy(route){return()=>{const old=location.hash;history.replaceState(null,'','#'+route);legacyRender();if(old&&old!=='#'+route)history.replaceState(null,'',old)}}['home','search','treatments','program','hospital','bid','bidform','bidresults','consult','hospitalDetail','treatmentDetail'].forEach(r=>DemoRouter.register(r,legacy(r)));DemoRouter.register('ai',()=>DemoRouter.go('aiIntake'));DemoRouter.register('aiIntake',legacy('aiIntake'));DemoRouter.register('airesult',legacy('airesult'));DemoRouter.register('aiPrograms',legacy('aiPrograms'));window.render=()=>DemoRouter.render();DemoRouter.start();})();